    24→
    25→/**
    26→ * This is an auxiliary function that selects the values for the circulant matrix in the FK20
    27→ * multiproof algorithm (Section 3) taking them from the coefficients of the input polynomial (for
    28→ * which the proofs are created).
    29→ *
    30→ * This function outputs the first column of the circulant matrix F''_i. The matrix F''_i is the
    31→ * padding of the Toeplitz matrix of size (r-1)·(r-1) to the size 2r·2r. It is supposed to output
    32→ * an array of size 2r that looks as follows:
    33→ *
    34→ *   out[0]      = in[d-i]
    35→ *   out[1..r+1] = 0
    36→ *   out[r+2]    = in[d-(r-2)l-i]
    37→ *   out[r+3]    = in[d-(r-3)l-i]
    38→ *   out[r+4]    = in[d-(r-4)l-i]
    39→ *   ...
    40→ *   out[2r-2]   = in[d-2l-i]
    41→ *   out[2r-1]   = in[d-1l-i]
    42→ *
    43→ * Where the following constants are:
    44→ *
    45→ *   d = FIELD_ELEMENTS_PER_BLOB-1
    46→ *   r = CELLS_PER_BLOB
    47→ *   l = FIELD_ELEMENTS_PER_CELL
    48→ *   i = offset
    49→ *
    50→ * @param[out]  out     The reordered polynomial, length 2*CELLS_PER_BLOB
    51→ * @param[in]   in      The input polynomial, length FIELD_ELEMENTS_PER_BLOB
    52→ * @param[in]   offset  The offset, an integer between 0 and FIELD_ELEMENTS_PER_BLOB-1, inclusive
    53→ */
    54→static void circulant_coeffs_stride(fr_t *out, const fr_t *in, size_t offset) {
    55→    const size_t r = CELLS_PER_BLOB;
    56→    const size_t l = FIELD_ELEMENTS_PER_CELL;
    57→    const size_t d = FIELD_ELEMENTS_PER_BLOB - 1;
    58→    const size_t d_minus_i = d - offset; /* Shortcut for: d-i */
    59→
    60→    assert(d >= offset);
    61→
    62→    /* Let's zero-initialise the whole output vector (length 2r) */
    63→    for (size_t j = 0; j < 2 * r; j++) {
    64→        out[j] = FR_ZERO;
    65→    }
    66→
    67→    /* First non-zero element is in[d-i] */
    68→    out[0] = in[d_minus_i];
    69→
    70→    /*
    71→     * Now we need to fill the remaining non-zero entries, which start at out[r+2] and finish at the
    72→     * end of the buffer out[2r-1]. That's r-2 elements from in[d-(r-2)l-i] to in[d-l-i].
    73→     */
    74→    for (size_t j = 1; j < r - 1; j++) { /* j = 1 ... r-2 */
    75→        out[2 * r - j] = in[d_minus_i - j * l];
    76→    }
    77→}
    78→
    79→/**
    80→ * Compute FK20 cell-proofs for a polynomial. Each cell-proof is a KZG multi-proof that proves that
    81→ * the input polynomial takes certain values in several points, concretely in
    82→ * FIELD_ELEMENTS_PER_CELL points.
    83→ *
    84→ * A naive way to construct the proofs would take time quadratic in the number of proofs. A more
    85→ * efficient way is to use an algorithm called FK20, documented in
    86→ * https://eprint.iacr.org/2023/033.pdf.
    87→ *
    88→ * The FK20 algorithm for n multi-proofs, each covering l evaluation points of a polynomial of
    89→ * degree d, dictates (Theorem 2 and Proposition 4) to proceed in two phases. The total complexity
    90→ * of this algorithm is 2rl·log(2r) for Phase 1, plus n·log(n) for Phase 2.
    91→ *
    92→ *   Phase 1: Compute the coefficients of a polynomial v(X) of degree r-1.
    93→ *
    94→ *     Observations:
    95→ *
    96→ *     1) The coefficients are computed as a sum of l matrix-vector products, where each matrix is
    97→ *        a Toeplitz matrix of size (r-1)·(r-1) (zeros below the main diagonal) composed from
    98→ *        certain coefficients of the input polynomial and a vector is a subvector of the KZG
    99→ *        trusted setup.
   100→ *     2) Each matrix-vector product is reduced to the product of a bigger circulant matrix by a
   101→ *        twice longer vector s_i.
   102→ *     3) The circulant matrix-vector product is best computed via FFT, so that the matrix is 2r·2r
   103→ *        (which are powers of two), thus little bigger than twice the Toeplitz matrix.
   104→ *
   105→ *     Computations:
   106→ *
